#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> set1 = {1, 3, 5, 7, 9};
    std::vector<int> set2 = {2, 3, 5, 7, 11};
    std::vector<int> intersection_result;
    // Reserve space to optimize memory allocation
    intersection_result.reserve(std::min(set1.size(), set2.size()));
    // Compute intersection of the two sorted sets
    auto it_end = std::set_intersection(set1.begin(), set1.end(),
                                        set2.begin(), set2.end(),
                                        std::back_inserter(intersection_result));
    // Output the intersection elements
    std::cout << "Intersection: ";
    for (int num : intersection_result) {
        std::cout << num << " ";
    }
    std::cout << std::endl;
    return 0;
}
